(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-233":{scenario:{legacy:"E"},learning:{summary:{vi:"Quản lý vận hành kho hàng và hệ thống WMS điều hành toàn bộ dòng hàng trong kho: nhận hàng, cất hàng, lưu trữ, lấy hàng, đóng gói, xuất hàng và kiểm kê, đồng thời quản trị dữ liệu vị trí và tồn kho trên WMS. Mục tiêu là tồn kho chính xác, xuất đúng hàng đúng hạn theo FIFO/FEFO, năng suất cao và an toàn tuyệt đối cho người, hàng hóa, thiết bị.",en:"A warehouse operations and WMS coordinator runs the full flow of goods in the warehouse: receiving, put-away, storage, picking, packing, shipping and stock counts, while managing location and inventory data in the WMS. The goal is accurate stock, the right goods shipped on time under FIFO/FEFO, high productivity and full safety for people, goods and equipment."},responsibilities:{vi:["Lập kế hoạch nhân lực, thiết bị cho nhận hàng và xuất hàng theo lịch đơn, lịch xe.","Kiểm soát nhận hàng: đối chiếu ASN, số lượng, lô, hạn dùng và tình trạng bao bì trước khi nhập WMS.","Quản lý vị trí lưu trữ (slotting), quy tắc FIFO/FEFO và luồng lấy hàng trên WMS.","Tổ chức kiểm kê luân phiên, xử lý chênh lệch tồn kho và báo cáo nguyên nhân gốc.","Bảo đảm an toàn xe nâng, kệ chứa, phòng cháy chữa cháy và 5S trong toàn kho."],en:["Plan labour and equipment for receiving and shipping against order and truck schedules.","Control receiving: check the ASN, quantities, lots, expiry dates and packaging before posting to the WMS.","Manage slotting, FIFO/FEFO rules and picking flows in the WMS.","Run cycle counts, resolve stock variances and report root causes.","Ensure forklift, racking, fire safety and 5S standards across the warehouse."]},competencies:[{name:{vi:"Vận hành WMS",en:"WMS operations"},desc:{vi:"Cấu hình vị trí, quy tắc cất, lấy hàng và đọc báo cáo ngoại lệ trên WMS.",en:"Configure locations, put-away and picking rules, and read WMS exception reports."}},{name:{vi:"Kiểm soát tồn kho",en:"Inventory accuracy control"},desc:{vi:"Thiết kế kiểm kê luân phiên theo ABC, truy nguyên chênh lệch và điều chỉnh có phê duyệt.",en:"Design ABC-based cycle counts, trace variances and post adjustments only with approval."}},{name:{vi:"Tối ưu năng suất kho",en:"Warehouse productivity"},desc:{vi:"Bố trí slotting, chọn phương pháp lấy hàng theo đơn, theo đợt hoặc theo vùng.",en:"Optimize slotting and choose order, batch or zone picking methods."}},{name:{vi:"An toàn & PCCC",en:"Safety & fire prevention"},desc:{vi:"Duy trì kiểm định xe nâng, tải trọng kệ, lối thoát nạn và huấn luyện an toàn định kỳ.",en:"Keep forklift inspections, rack load limits, escape routes and safety training up to date."}},{name:{vi:"Lãnh đạo ca kho",en:"Shift leadership"},desc:{vi:"Phân công, kèm cặp đội ngũ và phối hợp vận tải, mua hàng, kinh doanh.",en:"Assign and coach the team and coordinate with transport, purchasing and sales."}}],knowledge:{vi:["Nguyên tắc xuất kho FIFO, FEFO và quản lý lô, hạn dùng cho hàng có thời hạn sử dụng.","Kiểm kê luân phiên (cycle count) theo phân loại ABC và chỉ số độ chính xác tồn kho theo vị trí.","Chuẩn mã vạch GS1 (GTIN, SSCC) và quét mã trong nhận, cất, lấy, xuất hàng.","Luật An toàn, vệ sinh lao động 2015 (số 84/2015/QH13): xe nâng hàng thuộc nhóm thiết bị có yêu cầu nghiêm ngặt về an toàn, phải kiểm định theo quy định.","Quy định hiện hành về phòng cháy chữa cháy đối với kho hàng: khoảng cách xếp hàng, lối thoát nạn, hệ thống báo cháy."],en:["FIFO and FEFO issuing rules and lot and expiry management for shelf-life goods.","ABC-based cycle counting and location-level inventory accuracy.","GS1 barcode standards (GTIN, SSCC) and scanning in receiving, put-away, picking and shipping.","Occupational Safety and Health Law 2015 (No. 84/2015/QH13): forklifts are equipment with strict safety requirements and must be inspected as regulated.","Current fire safety rules for warehouses: storage clearances, escape routes and fire alarm systems."]},tools:["Hệ thống quản lý kho (WMS)","Máy quét mã vạch cầm tay (RF)","Xe nâng, xe nâng tay điện","Máy in nhãn mã vạch","Bảng điều khiển KPI kho"],kpis:{vi:["Độ chính xác tồn kho theo vị trí (mục tiêu từ 99,5%).","Tỷ lệ đơn xuất đúng, đủ, đúng hạn.","Năng suất lấy hàng (dòng/giờ) và thời gian từ nhận hàng đến sẵn sàng bán.","Số sự cố an toàn lao động (mục tiêu bằng 0)."],en:["Location-level inventory accuracy (target 99.5% or higher).","Share of orders shipped correct, complete and on time.","Picking productivity (lines per hour) and dock-to-stock time.","Workplace safety incidents (target zero)."]},day:[{time:"07:00",vi:"Họp đầu ca: an toàn, kế hoạch nhận xuất, phân công khu vực và thiết bị.",en:"Shift briefing: safety, receiving and shipping plan, zone and equipment assignments."},{time:"09:00",vi:"Giám sát nhận hàng, đối chiếu ASN, lô, hạn dùng và xử lý hàng sai lệch.",en:"Supervise receiving, check the ASN, lots and expiry dates and handle discrepancies."},{time:"11:00",vi:"Theo dõi các đợt lấy hàng trên WMS, điều chỉnh nhân lực cho đơn gấp.",en:"Monitor picking waves in the WMS and shift labour to urgent orders."},{time:"14:00",vi:"Kiểm kê luân phiên nhóm hàng A, truy nguyên chênh lệch với dữ liệu WMS.",en:"Cycle count class A items and trace variances against WMS data."},{time:"16:30",vi:"Chốt xuất hàng, kiểm tra niêm phong xe, báo cáo KPI và sự cố trong ngày.",en:"Close shipping, check truck seals and report daily KPIs and incidents."}],mistakes:{vi:["Cho xuất theo vị trí gần nhất thay vì theo FEFO, để hàng cận hạn tồn lại.","Điều chỉnh tồn kho trên WMS cho khớp số đếm mà không truy nguyên nguyên nhân và không có phê duyệt.","Cho người chưa có chứng chỉ vận hành xe nâng hoặc xếp hàng vượt tải trọng kệ để kịp chuyến."],en:["Picking from the nearest location instead of FEFO, leaving near-expiry stock behind.","Adjusting WMS stock to match the count without tracing the cause or getting approval.","Letting uncertified staff drive forklifts or overloading racks to make a truck on time."]},career:[{vi:"Nhân viên kho",en:"Warehouse associate"},{vi:"Tổ trưởng ca kho",en:"Warehouse shift supervisor"},{vi:"Quản lý vận hành kho & WMS",en:"Warehouse operations & WMS manager"},{vi:"Giám đốc trung tâm phân phối",en:"Distribution center director"}],glossary:[{term:"WMS",vi:"Hệ thống quản lý kho: điều khiển nhận, cất, lấy, xuất hàng và tồn kho theo vị trí.",en:"Warehouse management system controlling receiving, put-away, picking, shipping and location stock."},{term:"FEFO",vi:"Hết hạn trước xuất trước: ưu tiên xuất lô có hạn dùng sớm nhất.",en:"First expired, first out: the lot with the earliest expiry date ships first."},{term:"ASN",vi:"Thông báo giao hàng trước của nhà cung cấp: số lượng, lô, thời gian đến dự kiến.",en:"Advance shipping notice from the supplier with quantities, lots and expected arrival."},{term:"Slotting",vi:"Bố trí vị trí lưu trữ theo tần suất lấy hàng, kích thước và trọng lượng để tối ưu năng suất.",en:"Assigning storage locations by pick frequency, size and weight to maximize productivity."},{term:"Cycle count",vi:"Kiểm kê luân phiên từng nhóm vị trí theo lịch thay vì dừng kho kiểm kê toàn bộ.",en:"Counting groups of locations on a rolling schedule instead of shutting down for a full count."}],quiz:[{q:{vi:"Lô A hạn dùng 10/2027 nhập trước, lô B hạn dùng 03/2027 nhập sau. Theo FEFO xuất lô nào trước?",en:"Lot A (expiry 10/2027) arrived first; lot B (expiry 03/2027) arrived later. Under FEFO, which ships first?"},options:{vi:["Lô A vì nhập trước","Lô nào gần cửa hơn","Lô B vì hạn dùng sớm hơn","Chia đều hai lô"],en:["Lot A because it arrived first","Whichever is nearer the door","Lot B because it expires sooner","Split both lots evenly"]},answer:2,explain:{vi:"FEFO ưu tiên hạn dùng sớm nhất, không phụ thuộc thứ tự nhập kho.",en:"FEFO prioritizes the earliest expiry date regardless of arrival order."}},{q:{vi:"Kiểm kê 400 vị trí, có 6 vị trí sai lệch. Độ chính xác tồn kho theo vị trí là bao nhiêu?",en:"A count of 400 locations finds 6 with variances. What is location accuracy?"},options:{vi:["98,5%","99,4%","94,0%","96,5%"],en:["98.5%","99.4%","94.0%","96.5%"]},answer:0,explain:{vi:"(400 - 6) / 400 = 98,5%, thấp hơn mục tiêu 99,5% nên cần truy nguyên nguyên nhân.",en:"(400 - 6) / 400 = 98.5%, below the 99.5% target, so root causes must be traced."}},{q:{vi:"Cuối ca gấp chuyến, tổ trưởng bảo một nhân viên chưa có chứng chỉ lái xe nâng. Bạn làm gì?",en:"At shift end a supervisor tells an uncertified worker to drive a forklift to make a truck. What do you do?"},options:{vi:["Đồng ý vì chỉ một chuyến","Cho lái nhưng có người đứng xem","Để tổ trưởng tự chịu trách nhiệm","Dừng lại, bố trí người có chứng chỉ hoặc lùi chuyến và báo quản lý"],en:["Agree since it is just one load","Let him drive with someone watching","Leave it to the supervisor's responsibility","Stop it, assign a certified driver or delay the truck and inform the manager"]},answer:3,explain:{vi:"Vận hành xe nâng phải được huấn luyện, có chứng chỉ; an toàn luôn đặt trước tiến độ.",en:"Forklift operation requires training and certification; safety always comes before schedule."}},{q:{vi:"Mục đích của kiểm kê luân phiên theo ABC là gì?",en:"What is the purpose of ABC-based cycle counting?"},options:{vi:["Thay thế hoàn toàn WMS","Kiểm hàng giá trị cao thường xuyên hơn mà không dừng kho","Giảm số lượng nhân viên kho","Chỉ kiểm hàng hư hỏng"],en:["Replace the WMS entirely","Count high-value items more often without stopping operations","Reduce warehouse headcount","Count damaged goods only"]},answer:1,explain:{vi:"Nhóm A được đếm dày hơn để giữ độ chính xác cho hàng giá trị cao mà kho vẫn vận hành.",en:"Class A items are counted more often to protect accuracy on high-value stock while operations continue."}}],tools_en:["Warehouse management system (WMS)","Handheld RF barcode scanner","Forklifts and electric pallet jacks","Barcode label printer","Warehouse KPI dashboard"]}}})})(window.KKR);
